The feature is computing correctly — `days_since_last_maint` returns meaningful values (e.g., 92, 141 days) for later shipments where prior maintenance records exist, and NULL for early shipments before any maintenance was logged.

Here is the final validated query DTO:

```json
{
  // FROM shipments (aliased as "s") — the main grain of the output
  "from": "shipments",
  "fromAlias": "s",

  "selector": {
    "@type": "multi",
    "expressions": [
      {
        "alias": "shipmentId",
        "expression": { "@type": "path", "path": "s.shipmentId" }
      },
      {
        // Navigate the FK reference s.vehicleId → vehicles.vehicleId
        "alias": "vehicleId",
        "expression": { "@type": "path", "path": "s.vehicleId.vehicleId" }
      },
      {
        "alias": "shipment_date",
        "expression": { "@type": "path", "path": "s.date" }
      },
      {
        // SUBTRACT two dates → integer number of days difference
        "alias": "days_since_last_maint",
        "expression": {
          "@type": "binary",
          "operator": "SUBTRACT",
          "left": { "@type": "path", "path": "s.date" },

          // Correlated scalar subquery: MAX(maintenance_log.date)
          // for the same vehicle where maint date < shipment date
          "right": {
            "@type": "subquery",
            "query": {
              "from": "maintenance_log",
              "fromAlias": "m",
              "selector": {
                "@type": "single",
                "alias": "max_date",
                "expression": {
                  "@type": "aggregation",
                  "functionName": "MAX",
                  "arguments": [{ "@type": "path", "path": "date" }],
                  "distinct": false
                }
              },
              "where": {
                "@type": "binary",
                "operator": "AND",
                "left": {
                  // Join condition: same vehicle (FK navigation on both sides)
                  "@type": "binary",
                  "operator": "EQUALS",
                  "left":  { "@type": "path",     "path": "vehicleId.vehicleId" },
                  "right": { "@type": "outerRef",  "depth": 1, "path": "vehicleId.vehicleId" }
                },
                "right": {
                  // Temporal guard: only maintenance BEFORE the shipment date
                  "@type": "binary",
                  "operator": "LESS_THAN",
                  "left":  { "@type": "path",    "path": "date" },
                  "right": { "@type": "outerRef", "depth": 1, "path": "date" }
                }
              }
            }
          }
        }
      }
    ]
  },

  // Order descending to surface rows with non-null values first
  "orderBy": [
    { "ascending": false, "expression": { "@type": "path", "path": "s.date" } }
  ],
  "limit": 10
}
```

